SELECT School
FROM schools
WHERE County = 'Alameda' AND (Charter = 1 OR EILCode = 'ELEM');

SELECT DISTINCT School
FROM schools
WHERE County = 'Alameda' AND (Charter = 1 OR SOC = '60');

SELECT School FROM schools WHERE County = 'Alameda' AND Charter = 1
UNION
SELECT School FROM schools WHERE County = 'Alameda' AND SOCType LIKE '%Elementary%';
